codeExample:
console.log("1. Main Thread Start");

// Macrotask (Timers Phase of Event Loop)
setTimeout(() => {
  console.log("4. setTimeout (Macrotask Queue)");
}, 0);

// Microtask (VIP Priority! Skips the Event Loop phases)
Promise.resolve().then(() => {
  console.log("3. Promise Resolved (Microtask Queue)");
});

console.log("2. Main Thread End");

// OUTPUT ORDER:
// 1. Main Thread Start
// 2. Main Thread End
// 3. Promise Resolved (VIP Queue runs before Event Loop starts!)
// 4. setTimeout (Event Loop finally starts)
